select public._wave13_upsert_formula_tools('marketing-tools',$json$[{"slug":"marketing-revenue-per-campaign-calculator","title_ar":"حاسبة الإيراد لكل حملة تسويقية","title_en":"Marketing Revenue per Campaign Calculator","expression":"attributed_revenue / campaigns","fields":[{"key":"attributed_revenue","ar":"الإيراد المنسوب","en":"Attributed revenue","min":0,"step":0.01},{"key":"campaigns","ar":"عدد الحملات","en":"Campaigns","min":1e-06,"step":0.01}],"sort_order":33501},{"slug":"marketing-lead-share-calculator","title_ar":"حاسبة حصة العملاء المحتملين التسويقيين","title_en":"Marketing Lead Share Calculator","expression":"marketing_leads / total_leads * 100","fields":[{"key":"marketing_leads","ar":"العملاء المحتملون من التسويق","en":"Marketing leads","min":0,"step":0.01},{"key":"total_leads","ar":"إجمالي العملاء المحتملين","en":"Total leads","min":1e-06,"step":0.01}],"sort_order":33502},{"slug":"marketing-mql-rate-calculator","title_ar":"حاسبة معدل MQL","title_en":"Marketing MQL Rate Calculator","expression":"mqls / leads * 100","fields":[{"key":"mqls","ar":"العملاء المحتملون المؤهلون تسويقيًا","en":"MQLs","min":0,"step":0.01},{"key":"leads","ar":"العملاء المحتملون","en":"Leads","min":1e-06,"step":0.01}],"sort_order":33503},{"slug":"marketing-sql-rate-calculator","title_ar":"حاسبة معدل SQL","title_en":"Marketing SQL Rate Calculator","expression":"sqls / mqls * 100","fields":[{"key":"sqls","ar":"العملاء المحتملون المؤهلون للمبيعات","en":"SQLs","min":0,"step":0.01},{"key":"mqls","ar":"MQLs","en":"MQLs","min":1e-06,"step":0.01}],"sort_order":33504},{"slug":"marketing-opportunity-rate-calculator","title_ar":"حاسبة تحول التسويق إلى فرص","title_en":"Marketing Opportunity Rate Calculator","expression":"opportunities / leads * 100","fields":[{"key":"opportunities","ar":"الفرص","en":"Opportunities","min":0,"step":0.01},{"key":"leads","ar":"العملاء المحتملون","en":"Leads","min":1e-06,"step":0.01}],"sort_order":33505},{"slug":"marketing-campaign-efficiency-calculator","title_ar":