al revenue","min":1e-06,"step":0.01}],"sort_order":33510}]$json$::jsonb);
select public._wave13_upsert_formula_tools('business-tools',$json$[{"slug":"business-revenue-growth-rate-calculator","title_ar":"حاسبة نمو إيرادات الأعمال","title_en":"Business Revenue Growth Rate Calculator","expression":"(new_revenue - old_revenue) / old_revenue * 100","fields":[{"key":"old_revenue","ar":"الإيراد السابق","en":"Previous revenue","min":1e-06,"step":0.01},{"key":"new_revenue","ar":"الإيراد الجديد","en":"New revenue","min":0,"step":0.01}],"sort_order":33601},{"slug":"business-expense-growth-rate-calculator","title_ar":"حاسبة نمو مصروفات الأعمال","title_en":"Business Expense Growth Rate Calculator","expression":"(new_expenses - old_expenses) / old_expenses * 100","fields":[{"key":"old_expenses","ar":"المصروفات السابقة","en":"Previous expenses","min":1e-06,"step":0.01},{"key":"new_expenses","ar":"المصروفات الجديدة","en":"New expenses","min":0,"step":0.01}],"sort_order":33602},{"slug":"business-operating-margin-calculator","title_ar":"حاسبة هامش تشغيل الأعمال","title_en":"Business Operating Margin Calculator","expression":"operating_profit / revenue * 100","fields":[{"key":"operating_profit","ar":"الربح التشغيلي","en":"Operating profit","min":0,"step":0.01},{"key":"revenue","ar":"الإيراد","en":"Revenue","min":1e-06,"step":0.01}],"sort_order":33603},{"slug":"business-overhead-rate-calculator","title_ar":"حاسبة نسبة المصروفات العامة","title_en":"Business Overhead Rate Calculator","expression":"overhead_cost / revenue * 100","fields":[{"key":"overhead_cost","ar":"المصروفات العامة","en":"Overhead cost","min":0,"step":0.01},{"key":"revenue","ar":"الإيراد","en":"Revenue","min":1e-06,"step":0.01}],"sort_order":33604},{"slug":"business-revenue-per-employee-calculator","title_ar":"حاسبة إيراد الأعمال لكل موظف","title_en":"Business Revenue per Employee Calculator","expression":"revenue / employees","fields":[{"key":"revenue","ar":"الإيراد","en":"Revenue","min":0,"step":0.01},{"key":"employees","ar":"عدد الموظفين","en":"Employees","min":1e-06,"step":0.01}],"sort_or